// Valida lo que manda el sitio. NUNCA confiamos en el precio del navegador:
// el precio se lee de Supabase en el siguiente paso.
const b = $input.first().json.body || {};
const limpio = (s, n) => String(s ?? '').trim().slice(0, n);
const out = {
  eventoId: limpio(b.eventoId, 100),
  cantidad: parseInt(b.cantidad, 10),
  nombre: limpio(b.nombre, 120),
  email: limpio(b.email, 160).toLowerCase(),
  telefono: limpio(b.telefono, 30).replace(/[^0-9+]/g, ''),
};
let error = null;
if (!/^[a-z0-9-]{3,100}$/.test(out.eventoId)) error = 'Concierto inválido';
else if (!(out.cantidad >= 1 && out.cantidad <= 10)) error = 'Cantidad inválida (1 a 10 boletos)';
else if (out.nombre.length < 3) error = 'Escribe tu nombre completo';
else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(out.email)) error = 'Correo inválido';
else if (out.telefono.replace(/\D/g, '').length < 10) error = 'Teléfono inválido';
// Si hay error, usamos un id imposible para que la consulta no devuelva nada
if (error) out.eventoId = 'x-invalido';
return [{ json: { ...out, error } }];

const datos = $('Validar datos').first().json;
const ev = $('Leer concierto').all().map(i => i.json).find(e => e && e.id === datos.eventoId);
const vendidos = $('Leer ventas del concierto').all().map(i => i.json)
  .filter(v => v && v.cantidad).reduce((a, v) => a + Number(v.cantidad), 0);
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Mexico_City' }).format(new Date());

let error = datos.error;
if (!error && !ev) error = 'Concierto no encontrado';
if (!error && ev.estado !== 'venta') error = 'Este concierto no tiene venta en línea';
if (!error && !(Number(ev.precio) > 0)) error = 'Precio no configurado';
if (!error && ev.fecha < hoy) error = 'Este concierto ya pasó';
if (!error && ev.cupo != null && vendidos + datos.cantidad > ev.cupo) {
  const quedan = Math.max(0, ev.cupo - vendidos);
  error = quedan ? `Sólo quedan ${quedan} boletos` : 'Boletos agotados';
}
if (error) return [{ json: { ok: false, error } }];

const meses = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
const [y, m, d] = ev.fecha.split('-').map(Number);
const expira = new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString().replace('Z', '-00:00');

const preferencia = {
  items: [{
    id: ev.id,
    title: `Boleto ${ev.artista} · ${ev.ciudad} · ${d} ${meses[m - 1]} ${y}`,
    description: `${ev.lugar}${ev.hora ? ' · ' + ev.hora + ' h' : ''}`,
    category_id: 'tickets',
    quantity: datos.cantidad,
    unit_price: Number(ev.precio),
    currency_id: 'MXN',
  }],
  payer: { name: datos.nombre, email: datos.email },
  back_urls: {
    success: 'https://gyrarte.com/gracias/?estado=ok',
    pending: 'https://gyrarte.com/gracias/?estado=pendiente',
    failure: 'https://gyrarte.com/gracias/?estado=error',
  },
  auto_return: 'approved',
  notification_url: 'https://n8n.srv964593.hstgr.cloud/webhook/gyrarte-mp-webhook',
  external_reference: `gyrarte|${ev.id}|${Date.now()}`,
  statement_descriptor: 'GYRARTE',
  expires: true,
  expiration_date_to: expira,
  metadata: {
    origen: 'gyrarte',
    evento_id: ev.id,
    cantidad: datos.cantidad,
    nombre: datos.nombre,
    email: datos.email,
    telefono: datos.telefono,
  },
};
return [{ json: { ok: true, preferencia } }];
